        placeholder="yyyy-mm-dd"
        value={from[settingKey] ?? ''}
        onChange={(e) => {
          const value = e.target.value;
          setFrom((v) => ({ ...v, [settingKey]: value }));
          onChange();
        }}
      />
    </label>
  );
}

