package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PoolRepository {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    private final JdbcTemplate jdbc;

    public PoolRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public boolean sheetExists(String sheetId) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId);
        return known != null && known > 0;
    }

    public boolean exists(String sheetId, String name) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM pool WHERE sheet_id = ? AND name = ?",
                Integer.class, sheetId, name);
        return known != null && known > 0;
    }

    /** The person's name, or null when they are not on the sheet. */
    public String personName(String sheetId, long personId) {
        List<String> names = jdbc.queryForList("SELECT name FROM person WHERE sheet_id = ? AND id = ?",
                String.class, sheetId, personId);
        return names.isEmpty() ? null : names.get(0);
    }

    /** Add a pool; false when the sheet already has one of that name. */
    public boolean add(String sheetId, String name) {
        try {
            jdbc.update("INSERT INTO pool (sheet_id, name) VALUES (?, ?)", sheetId, name);
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** Add a member to a pool; false when the person is already in it. */
    public boolean addMember(String sheetId, String pool, long personId, BigDecimal share) {
        try {
            jdbc.update("INSERT INTO pool_member (sheet_id, pool_name, person_id, share) VALUES (?, ?, ?, ?)",
                    sheetId, pool, personId, share);
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** The sheet's pools, by name, each with its members in the order they were added. */
    public List<Pool> list(String sheetId) {
        Map<String, List<PoolMember>> members = new LinkedHashMap<>();
        for (String name : jdbc.queryForList("SELECT name FROM pool WHERE sheet_id = ? ORDER BY name", String.class,
                sheetId)) {
            members.put(name, new ArrayList<>());
        }
        jdbc.query("SELECT m.pool_name, m.person_id, p.name, m.share, p.retired_from FROM pool_member m"
                + " JOIN person p ON p.id = m.person_id WHERE m.sheet_id = ? ORDER BY m.id", rs -> {
            List<PoolMember> of = members.get(rs.getString("pool_name"));
            if (of != null) {
                of.add(new PoolMember(rs.getLong("person_id"), rs.getString("name"),
                        rs.getBigDecimal("share").setScale(2).toPlainString(), rs.getDate("retired_from") != null));
            }
        }, sheetId);
        List<Pool> pools = new ArrayList<>();
        members.forEach((name, of) -> {
            BigDecimal total = of.stream().filter(m -> !m.retired()).map(m -> new BigDecimal(m.share()))
                    .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
            pools.add(new Pool(name, of, total.toPlainString(), total.compareTo(HUNDRED) == 0));
        });
        return pools;
    }
}
-- A sheet's pools: a name (unique on the sheet, trimmed, not blank).
CREATE TABLE pool (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(500) NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
-- A pool's members: a person on the sheet (at most once per pool) with a share percent (more than 0.00,
-- at most 100.00, two decimals), listed in the order they were added (by id). A retired member's share
-- counts as 0.00 toward the pool's total.
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    pool_name VARCHAR(500)  NOT NULL,
    person_id BIGINT        NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL CHECK (share > 0 AND share <= 100),
    UNIQUE (sheet_id, pool_name, person_id)
);
import { useState, type ChangeEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { usePeople, type Person } from '../people/usePeople';
import { poolsKey, usePools, type Pool } from './usePools';

/** One pool: its members with their shares, its total share and whether it is balanced, and a form that
 *  adds a member (a person on the sheet and a share percent). */
function PoolRow({ sheetId, pool, people }: { sheetId: string; pool: Pool; people: Person[] }) {
  const queryClient = useQueryClient();
  const [personId, setPersonId] = useState('');
  const [share, setShare] = useState('');

  const submitOnce = useSingleFlight();
  const add = useMutation({
    mutationFn: (f: { pool: string; personId: number | null; share: string }) =>
      postJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools/members`, f),
    onSuccess: async () => {
      setPersonId('');
      setShare('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
  });

  return (
    <div data-testid={`pool-row-${pool.name}`}>
      <strong data-testid="pool-name">{pool.name}</strong>{' '}
      Total <span data-testid="pool-total-share">{pool.totalShare}</span>{' '}
      Balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li key={m.personId} data-testid={`pool-member-${pool.name}-${m.personId}`}>
            <span data-testid="pool-member-name">{m.name}</span>{' '}
            <span data-testid="pool-share">{m.share}</span>
            {m.retired && ' (retired)'}
          </li>
        ))}
      </ul>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ pool: pool.name, personId: personId === '' ? null : Number(personId), share });
          });
        }}
      >
        <select
          data-testid="pool-member-select"
          value={personId}
          onChange={(e: ChangeEvent<HTMLSelectElement>) => {
            setPersonId(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a person</option>
          {people.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <label>
          Share{' '}
          <input
            data-testid="pool-member-share"
            inputMode="decimal"
            value={share}
            onChange={(e) => {
              setShare(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
      </form>
      {add.isError && <p data-testid="pool-error">{add.error.message}</p>}
    </div>
  );
}

/** The sheet's pools: a form that adds one (a name, unique on the sheet) and each pool with its members. */
function Pools({ sheetId }: { sheetId: string }) {
  const pools = usePools(sheetId);
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const [name, setName] = useState('');

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { name: string }) =>
      postJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`, f),
    onSuccess: async () => {
      setName('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
  });

  return (
    <section data-testid="pools">
      <form
        data-testid="pool-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ name });
          });
        }}
      >
        <label>
          Pool{' '}
          <input
            data-testid="pool-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={save.isPending}>
          Add pool
        </button>
        {save.isError && <p data-testid="pool-form-error">{save.error.message}</p>}
      </form>
      {(pools.data ?? []).map((p) => (
        <PoolRow key={p.name} sheetId={sheetId} pool={p} people={people.data ?? []} />
      ))}
      {pools.isError && <p data-testid="pools-error">{pools.error.message}</p>}
    </section>
  );
}

